import org.apache.lucene.geo.*;
import org.apache.lucene.index.PointValues.Relation;
import org.apache.lucene.document.ShapeField;

public class Dbg {
  public static void main(String[] args) {
    final int base = Integer.MAX_VALUE;
    double plat = GeoEncodingUtils.decodeLatitude(base - 2);
    double plon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    System.out.println("point lat=" + plat + " lon=" + plon);
    System.out.println("poly lat=[" + minLat + "," + maxLat + "] lon=[" + minLon + "," + maxLon + "]");

    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D tree = LatLonGeometry.create(poly);
    System.out.println("tree bbox: x=[" + tree.getMinX() + "," + tree.getMaxX() + "] y=[" + tree.getMinY() + "," + tree.getMaxY() + "]");
    System.out.println("tree.contains(point): " + tree.contains(plon, plat));

    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
    int elat = GeoEncodingUtils.encodeLatitude(plat);
    int elon = GeoEncodingUtils.encodeLongitude(plon);
    System.out.println("encoded point lat=" + Integer.toHexString(elat) + " lon=" + Integer.toHexString(elon));
    System.out.println("pred.test(encoded): " + pred.test(elat, elon));

    // inspect grid
    Class<?> gridCls = pred.getClass().getSuperclass();
    for (String f : new String[] {"latShift", "lonShift", "latBase", "lonBase", "maxLatDelta", "maxLonDelta"}) {
      try {
        java.lang.reflect.Field fl = gridCls.getDeclaredField(f);
        fl.setAccessible(true);
        System.out.println(f + " = " + fl.get(pred));
      } catch (Exception e) { e.printStackTrace(); }
    }
    try {
      java.lang.reflect.Field fl = gridCls.getDeclaredField("relations");
      fl.setAccessible(true);
      byte[] rel = (byte[]) fl.get(pred);
      System.out.println("relations = " + java.util.Arrays.toString(rel));
    } catch (Exception e) { e.printStackTrace(); }

    // simulate grid computation
    double shapeMinY = tree.getMinY(), shapeMaxY = tree.getMaxY(), shapeMinX = tree.getMinX(), shapeMaxX = tree.getMaxX();
    int minLatE = GeoEncodingUtils.encodeLatitudeCeil(shapeMinY);
    int maxLatE = GeoEncodingUtils.encodeLatitude(shapeMaxY);
    int minLonE = GeoEncodingUtils.encodeLongitudeCeil(shapeMinX);
    int maxLonE = GeoEncodingUtils.encodeLongitude(shapeMaxX);
    System.out.println("grid lat=[" + minLatE + "," + maxLatE + "] lon=[" + minLonE + "," + maxLonE + "]");
    System.out.println("encodeLatitudeCeil(minLat double)=" + minLatE + " vs base-3=" + (base-3));
    System.out.println("encodeLatitude(maxLat double)=" + maxLatE + " vs base=" + base);
    System.out.println("encodeLongitudeCeil(minLon double)=" + minLonE + " vs base-3=" + (base-3));
    System.out.println("encodeLongitude(maxLon double)=" + maxLonE + " vs base=" + base);
  }
}
