              || (a1y > maxY && b1y > maxY)
              || (a1x < minX && b1x < minX)
              || (a1x > maxX && b1x > maxX);
      if (outside == false) {
        if (includeBoundary) {
          if (lineCrossesLineWithBoundary(a1x, a1y, b1x, b1y, a2x, a2y, b2x, b2y)) {
            return true;
