import org.apache.lucene.geo.*;
import java.lang.reflect.Field;

public class Dbg5 {
  static Field fl(Class<?> g, String n) throws Exception { Field f = g.getDeclaredField(n); f.setAccessible(true); return f; }

  public static void main(String[] args) throws Exception {
    final int base = Integer.MAX_VALUE;
    double plat = GeoEncodingUtils.decodeLatitude(base - 2);
    double plon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D tree = LatLonGeometry.create(poly);
    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
    int elat = GeoEncodingUtils.encodeLatitude(plat);
    int elon = GeoEncodingUtils.encodeLongitude(plon);
    Class<?> g = pred.getClass().getSuperclass();
    int latShift = (Integer) fl(g, "latShift").get(pred);
    int lonShift = (Integer) fl(g, "lonShift").get(pred);
    int latBase = (Integer) fl(g, "latBase").get(pred);
    int lonBase = (Integer) fl(g, "lonBase").get(pred);
    int maxLatDelta = (Integer) fl(g, "maxLatDelta").get(pred);
    int maxLonDelta = (Integer) fl(g, "maxLonDelta").get(pred);
    byte[] relations = (byte[]) fl(g, "relations").get(pred);

    System.out.println("elat=" + elat + " elon=" + elon);
    int lat2 = ((elat - Integer.MIN_VALUE) >>> latShift);
    System.out.println("lat2=" + lat2 + " latBase=" + latBase + " maxLatDelta=" + maxLatDelta);
    int lon2 = ((elon - Integer.MIN_VALUE) >>> lonShift);
    System.out.println("lon2=" + lon2 + " lonBase=" + lonBase + " wrap=" + (lon2 < lonBase));
    int idx = (lat2 - latBase) * maxLonDelta + (lon2 - lonBase);
    System.out.println("relation idx=" + idx + " value=" + relations[idx]);
    for (org.apache.lucene.index.PointValues.Relation r : org.apache.lucene.index.PointValues.Relation.values())
      System.out.println(r + " ordinal=" + r.ordinal());
    // replicate the contains call exactly as Component2DPredicate.test does
    System.out.println("contains(decodeLon(elon), decodeLat(elat)) = " + tree.contains(GeoEncodingUtils.decodeLongitude(elon), GeoEncodingUtils.decodeLatitude(elat)));
    System.out.println("pred.test = " + pred.test(elat, elon));
  }
}
